window.kbPageData["views/entry/k-9ef25c94314f0b3a"] = {"key":"entry/k-9ef25c94314f0b3a","state":{"route":"entry/k-9ef25c94314f0b3a"},"node":{"id":"k-9ef25c94314f0b3a","mode":"k","title":"危险废物管理计划与环境应急预案备案","type":"制度与规则","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["危险废物贮存管理计划、应急预案与演练培训"],"qs":["国考 2025 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"按2024年考试时适用的规定，产生危险废物的单位应制定危险废物管理计划，报所在地生态环境主管部门备案。产生、收集、贮存、运输、利用、处置危险废物的单位还应制定意外事故防范措施和应急预案，向所在地生态环境主管部门及其他负有固体废物污染环境防治监督管理职责的部门备案。","review":{"definition":"按2024年考试时适用的规定，产生危险废物的单位应制定危险废物管理计划，报所在地生态环境主管部门备案。产生、收集、贮存、运输、利用、处置危险废物的单位还应制定意外事故防范措施和应急预案，向所在地生态环境主管部门及其他负有固体废物污染环境防治监督管理职责的部门备案。","explanation":"管理计划涵盖减量减害和贮存、利用、处置安排，环境应急预案用于突发环境事件应对。企业环境应急预案一般在签署发布后20个工作日内向所在地县级生态环境主管部门备案。材料4报告西瑞药业已制定计划和预案并备案，还定期演练、组织员工培训，可分别写入谈话提纲的危废管理和应急准备成效。","references":[{"source":"web-500595e3e43719b7","location":"第七十八条、第八十五条","quote":"制定意外事故的防范措施和应急预案"},{"source":"web-f626b5f10086d03b","location":"第三条、第十四条","quote":"向企业所在地县级环境保护主管部门备案"},{"source":"web-9e6f394b54583111","location":"第十五条、第十九条","quote":"定期开展应急演练"}],"evidence":"危险废物管理计划及应急预案制度并备案","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2025 行政执法 申论#4":{"paper":"国考 2025 行政执法 申论","n":4,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3],"card":"e9b26cf35f72426e9b032d20","links":[{"id":"k-9ef25c94314f0b3a","role":"直接考查","why":"计划和预案备案、定期演练与员工培训共同支撑对企业危废管理和应急准备的评价。"}]}},"terms":{},"references":{"web-500595e3e43719b7":{"name":"中华人民共和国固体废物污染环境防治法（2020年修订）","url":"https://www.miit.gov.cn/jgsj/zfs/fl/art/2022/art_f2d9c145e29e4c93a442c8663c2c32ff.html"},"web-f626b5f10086d03b":{"name":"企业事业单位突发环境事件应急预案备案管理办法（试行）","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xzgfxwj/202301/W020150113590026890393.pdf"},"web-9e6f394b54583111":{"name":"突发环境事件应急管理办法","url":"https://www.mee.gov.cn/gkml/hbb/bl/201504/t20150429_299852.htm"}},"topics":[],"units":{"k-9ef25c94314f0b3a":[["国考 2025 行政执法 申论#4"]]}};
